const options = Array.from(rooms.values()).filter(item => item.sessionId && !item.stopped && !item.uncertain);
const active = rooms.get(selectedThread);
return `<div class="quick-row">
  <label>话题 <select id="workbench-topic" data-testid="workbench-topic-select" aria-label="选择话题">
    <option value="">新话题</option>
    ${options.map(item => `<option value="${esc(item.id)}"${item.id === selectedThread ? ' selected' : ''}>${esc(title(item))}</option>`).join('')}
  </select></label>
  ${active?.sessionId ? `<a class="q" data-testid="workbench-open-session" target="_top" href="/chat/${encodeURIComponent(active.sessionId)}?application=superagent">打开 WorkSwarm 会话${active.pendingApproval ? ' · 待审批' : ''}</a>` : ''}

document.addEventListener('change', event => {
  if (event.target.id !== 'workbench-topic') return;
  selectedThread = event.target.value;
  emit();
});
store.sendMessage = send;
